const express = require('express');
const { HTTP } = require('cloudevents');
const knex = require('knex')({ client: 'pg', connection: process.env.DB_URL });

const app = express();
app.use(express.json({ type: ['application/json', 'application/cloudevents+json'] }));

app.post('/api/grid-events/receiver', async (req, res) => {
  const authToken = req.headers['authorization'];
  if (!authToken) {
    return res.status(401).json({ error: 'Grid operator authorization required' });
  }

  const event = HTTP.toEvent({ headers: req.headers, body: req.body });

  if (event.type === 'com.utility.smartmeter.disconnect') {
    const meterId = event.subject.replace('urn:meter:', '');

    // Validate operator's sector authority over the smart meter
    const operator = await knex('grid_operators')
      .where({ api_token: authToken })
      .first();

    if (!operator) {
      return res.status(401).json({ error: 'Invalid operator credentials' });
    }

    const meter = await knex('smart_meters')
      .where({ id: meterId, utility_sector_id: operator.assigned_sector_id })
      .first();

    if (!meter) {
      return res.status(403).json({ error: 'Operator not authorized to command meters in this sector' });
    }

    await knex('smart_meters')
      .where({ id: meterId })
      .update({
        relay_state: 'DISCONNECTED',
        disconnected_at: new Date(),
        reason: event.data.reason
      });
  }

  res.status(200).json({ ack: true });
});

app.listen(9008);
